87	    private JSONObject makeJiraConnection(JiraAuth auth, JiraCall<JSONObject> jiraCall) {
88	        JSONObject callResponse = jiraCall.execute(auth.accessToken);
89	        if (callResponse.has("code") && callResponse.getInt("code") == 401) {
90	            String refreshedToken = refreshToken(auth);
91	            if (refreshedToken != null) {
92	                callResponse = jiraCall.execute(refreshedToken);
93	            }
94	        }
95	        return callResponse;
96	    }
