98	    private synchronized String refreshToken(JiraAuth auth) {
99	        try {
100	            String jiraCID = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_ID);
101	            String jiraClientSecret = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_SECRET);
102	
103	            if (CommonUtil.isEmpty(jiraCID, jiraClientSecret)) {
104	                LOGGER.log(Level.INFO, "Invalid Jira client id or client secret");
105	                return null;
106	            }
107	
108	            String tokenExchangeUrl = JIRA_BASE_URL + "/oauth/token";
109	
110	            JSONObject requestBody = new JSONObject();
111	            requestBody.put("grant_type", "refresh_token");
112	            requestBody.put("client_id", jiraCID);
113	            requestBody.put("client_secret", jiraClientSecret);
114	            requestBody.put("refresh_token", auth.refreshToken);
115	
116	            String tokenExchangeResponse = new HttpURLConnectionInvoker(true)
117	                    .invokePostHttpURLConnWithRequestBody(
118	                            tokenExchangeUrl,
119	                            null, null,
120	                            requestBody
121	                    );
122	
123	            JSONObject authExchangeJSONResponse = new JSONObject(tokenExchangeResponse);
124	
125	            String jiraRefreshToken = authExchangeJSONResponse.optString("refresh_token", null);
126	            String jiraAccessToken = authExchangeJSONResponse.optString("access_token", null);
127	            String jiraAccessExpiry = authExchangeJSONResponse.optString("expires_in", null);
128	            String jiraScope = authExchangeJSONResponse.optString("scope", null);
129	
130	            if (CommonUtil.isEmpty(jiraRefreshToken, jiraAccessToken, jiraAccessExpiry, jiraScope)) {
131	                return null;
132	            }
133	
134	            addOrUpdateJiraAuth(auth.projectId, auth.zsoId, jiraAccessToken, jiraRefreshToken);
135	            return jiraAccessToken;
136	
137	        } catch (Exception e) {
138	            LOGGER.log(Level.SEVERE, "Exception while Jira token rotation", e);
139	        }
140	        return null;
141	    }
