275	                    LOGGER.log(Level.SEVERE, "Exception while fetching Jira Projects", e);
276	                }
277	                return null;
278	            });
279	
280	            if (jiraResponse == null) {
281	                return null;
282	            }
283	
284	            ArrayList<JiraProject> jiraProjects = new ArrayList<>();
285	            JSONArray jiraProjectsJSONArray = jiraResponse.optJSONArray("values", null);
286	            if (jiraProjectsJSONArray == null) {
287	                return null;
