388	            if (jiraAuth == null) {
389	                LOGGER.log(Level.INFO, "Jira Auth is null");
390	                return false;
391	            }
392	
393	            JSONObject configuration = IntegrationHandler.getIntegrationDetailsByService(
394	                    AppticsConstants.JIRA,
395	                    moduleName,
396	                    "unique",
397	                    apId
398	            );
399	            if (configuration == null) {
400	                LOGGER.log(Level.INFO, "Jira Config is null");
401	                return false;
402	            }
403	
404	            LOGGER.log(Level.INFO, "Jira Config {0}", configuration.toString());
405	
406	            String jiraCloudId = configuration.getString("cloud_id");
407	            String jiraProjectId = configuration.getString("project_id");
408	            String jiraIssueTypeId = configuration.getString("issue_type_id");
409	
410	            if (CommonUtil.isEmpty(jiraProjectId, jiraIssueTypeId)) {
411	                return false;
412	            }
413	
414	            JSONObject jiraResponse = makeJiraConnection(jiraAuth, (String token) -> {
415	                if (CommonUtil.isEmpty(token, jiraCloudId)) {
416	                    return null;
417	                }
418	
419	                String addIssueUrl = JIRA_BASE_URL
420	                        + "/ex/jira/" + jiraCloudId
421	                        + "/rest/api/3/issue";
422	
423	                Map<String, String> headers = new HashMap<>();
424	                headers.put("Authorization", "Bearer " + token);
425	
426	                String createIssueResponse = new HttpURLConnectionInvoker(true)
427	                        .invokePostHttpURLConnWithRequestBody(
428	                                addIssueUrl,
429	                                headers,
430	                                null,
431	                                buildRequestBodyToCreateIssue(jiraProjectId, jiraIssueTypeId, issueTitle, issueDescription, crashLink)
432	                        );
433	                return new JSONObject(createIssueResponse);
434	            });
435	
436	            if (jiraResponse.has("id")) {
437	                return true;
438	            }
439	
440	        } catch (Exception e) {
441	            LOGGER.log(Level.SEVERE, "Exception while sending unique crash to Jira", e);
442	        }
443	        return false;
444	    }
