464	    private String getCloudIdFromAccessibleResources(JSONObject accessibleResources) throws JSONException {
465	        JSONArray resourcesArray = accessibleResources.getJSONArray("data");
466	
467	        for (int i = 0; i < resourcesArray.length(); i++) {
468	            JSONObject resource = resourcesArray.getJSONObject(i);
469	            JSONArray scopes = resource.getJSONArray("scopes");
470	            for (int j = 0; j < scopes.length(); j++) {
471	                if (scopes.getString(j).equals(JIRA_SCOPE)) {
472	                    return resource.getString("id");
473	                }
474	            }
475	        }
476	        return null;
477	    }
