494	
495	        JSONObject issueDescField = new JSONObject();
496	        issueDescField.put("type", "doc");
497	        issueDescField.put("version", 1);
498	
499	        JSONArray contentArr = new JSONArray();
500	
501	        // Paragraph 1
502	        JSONObject p1 = new JSONObject();
503	        p1.put("type", "paragraph");
504	
505	        JSONArray p1Content = new JSONArray();
506	        p1.put("content", p1Content);
507	
508	        JSONObject linkText = new JSONObject();
509	        linkText.put("type", "text");
510	        linkText.put("text", issueLink);
511	
512	        JSONArray marks = new JSONArray();
513	        JSONObject mark = new JSONObject();
514	        mark.put("type", "link");
515	
516	        JSONObject attrs = new JSONObject();
517	        attrs.put("href", issueLink);
518	
519	        mark.put("attrs", attrs);
520	        marks.put(mark);
521	
522	        linkText.put("marks", marks);
523	        p1Content.put(linkText);
524	
525	        // Add space text
526	        JSONObject spaceText = new JSONObject();
527	        spaceText.put("type", "text");
528	        spaceText.put("text", "  ");
529	        p1Content.put(spaceText);
530	
531	        contentArr.put(p1);
532	
533	        // Paragraph 2
534	        JSONObject p2 = new JSONObject();
535	        p2.put("type", "paragraph");
536	
537	        JSONArray p2Content = new JSONArray();
538	        p2.put("content", p2Content);
539	
540	        JSONObject stackText = new JSONObject();
541	        stackText.put("type", "text");
542	        stackText.put("text", issueDescription);
543	
544	        p2Content.put(stackText);
545	        contentArr.put(p2);
546	
547	        issueDescField.put("content", contentArr);
548	
549	        fields.put("project", projectField);
550	        fields.put("issuetype", issueTypeField);
551	        fields.put("summary", issueTitle);
552	        fields.put("description", issueDescField);
553	
554	        requestBody.put("fields", fields);
555	
556	        return requestBody;
