package com.zoho.apptics.integration;

import com.adventnet.ds.query.*;
import com.adventnet.persistence.Row;
import com.zoho.apptics.util.*;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

import java.util.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class JiraHandler {

    private static final Logger LOGGER = Logger.getLogger(JiraHandler.class.getName());
    private final String JIRA_BASE_URL = "https://api.atlassian.com";
    private final String JIRA_SCOPE = "write:jira-work";


    @FunctionalInterface
    private interface JiraCall<T> {
        T execute(String token);
    }

    public record JiraSites(
            String cloudId,
            String name
    ) {
        public JSONObject toJson() {
            JSONObject json = new JSONObject();
            json.put("name", name);
            json.put("cloud_id", cloudId);
            return json;
        }

        @Override
        public String toString() {
            return toJson().toString();
        }
    }

    record JiraAuth(
            String zsoId,
            long projectId,
            String accessToken,
            String refreshToken
    ) { }

    public record JiraProject(
            String projectName,
            String projectKey,
            String projectId
    ) {
        public JSONObject toJson() {
            JSONObject json = new JSONObject();
            json.put("project_name", projectName);
            json.put("project_key", projectKey);
            json.put("project_id", projectId);
            return json;
        }

