    private JSONObject makeJiraConnection(JiraAuth auth, JiraCall<JSONObject> jiraCall) {
        JSONObject callResponse = jiraCall.execute(auth.accessToken);
        if (callResponse.has("code") && callResponse.getInt("code") == 401) {
            String refreshedToken = refreshToken(auth);
            if (refreshedToken != null) {
                callResponse = jiraCall.execute(refreshedToken);
            }
        }
        return callResponse;
    }

    private synchronized String refreshToken(JiraAuth auth) {
        try {
            String jiraCID = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_ID);
            String jiraClientSecret = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_SECRET);

            if (CommonUtil.isEmpty(jiraCID, jiraClientSecret)) {
                LOGGER.log(Level.INFO, "Invalid Jira client id or client secret");
                return null;
            }

            String tokenExchangeUrl = JIRA_BASE_URL + "/oauth/token";

            JSONObject requestBody = new JSONObject();
            requestBody.put("grant_type", "refresh_token");
            requestBody.put("client_id", jiraCID);
            requestBody.put("client_secret", jiraClientSecret);
            requestBody.put("refresh_token", auth.refreshToken);

            String tokenExchangeResponse = new HttpURLConnectionInvoker(true)
                    .invokePostHttpURLConnWithRequestBody(
                            tokenExchangeUrl,
                            null, null,
                            requestBody
                    );

            JSONObject authExchangeJSONResponse = new JSONObject(tokenExchangeResponse);

            String jiraRefreshToken = authExchangeJSONResponse.optString("refresh_token", null);
            String jiraAccessToken = authExchangeJSONResponse.optString("access_token", null);
            String jiraAccessExpiry = authExchangeJSONResponse.optString("expires_in", null);
            String jiraScope = authExchangeJSONResponse.optString("scope", null);

            if (CommonUtil.isEmpty(jiraRefreshToken, jiraAccessToken, jiraAccessExpiry, jiraScope)) {
                return null;
            }

            addOrUpdateJiraAuth(auth.projectId, auth.zsoId, jiraAccessToken, jiraRefreshToken);
            return jiraAccessToken;

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while Jira token rotation", e);
        }
        return null;
    }

    public boolean authenticate(
            String code,
            String redirectUri,
            String zsoId,
            long projectId
    ) {
        String authExchangeUrl = JIRA_BASE_URL + "/oauth/token";

        String jiraCID = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_ID);
        String jiraClientSecret = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_SECRET);

        if (CommonUtil.isEmpty(jiraCID, jiraClientSecret)) {
            LOGGER.log(Level.INFO, "Invalid Jira client id or client secret");
            return false;
        }

        try {
            JSONObject requestBody = new JSONObject();
            requestBody.put("code", code);
            requestBody.put("redirect_uri", redirectUri);
            requestBody.put("grant_type", "authorization_code");
            requestBody.put("client_id", jiraCID);
            requestBody.put("client_secret", jiraClientSecret);

            String authExchangeResponse = new HttpURLConnectionInvoker(true).invokePostHttpURLConnWithRequestBody(
                    authExchangeUrl,
                    null,
                    null,
                    requestBody
            );
            LOGGER.log(Level.INFO, authExchangeResponse);
            JSONObject authExchangeJSONResponse = new JSONObject(authExchangeResponse);

            String jiraRefreshToken = authExchangeJSONResponse.optString("refresh_token", null);
            String jiraAccessToken = authExchangeJSONResponse.optString("access_token", null);
            String jiraAccessExpiry = authExchangeJSONResponse.optString("expires_in", null);
            String jiraScope = authExchangeJSONResponse.optString("scope", null);

            if (CommonUtil.isEmpty(jiraRefreshToken, jiraAccessToken, jiraAccessExpiry, jiraScope)) {
                return false;
            }
            addOrUpdateJiraAuth(projectId, zsoId, jiraAccessToken, jiraRefreshToken);

            return true;
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while authenticating Jira", e);
        }
        return false;
    }

    public List<JiraSites> getJiraSites(String zsoId, Long projectId) {
        try {
            JiraAuth jiraAuth = getJiraAuth(zsoId, projectId);
            if (jiraAuth == null) {
                return null;
            }

            JSONObject jiraResponse = makeJiraConnection(jiraAuth, (String token) -> {
                if (CommonUtil.isEmpty(token)) {
                    return null;
                }
                String accessibleResourcesUrl = JIRA_BASE_URL + "/oauth/token/accessible-resources";

                Map<String, String> headers = new HashMap<>();
                headers.put("Authorization", "Bearer " + token);
                headers.put("Accept", "application/json");
                LOGGER.log(Level.INFO , "Token {0}", token);
                try {
                    String accessibleResourcesResponse = new HttpURLConnectionInvoker(true)
                            .invokeGetHttpURLConn(
                                    accessibleResourcesUrl,
                                    headers,
                                    null
                            );
                    return new JSONObject(accessibleResourcesResponse);
                } catch (Exception e) {
                    LOGGER.log(Level.SEVERE, "Exception while fetching Jira Projects", e);
                }
                return null;
            });

            if (jiraResponse == null) {
                return null;
            }

            ArrayList<JiraSites> sites = new ArrayList<>();

            JSONArray resourcesArray = jiraResponse.getJSONArray("data");
            for (int i = 0; i < resourcesArray.length(); i++) {
                JSONObject resource = resourcesArray.getJSONObject(i);
                JiraSites site = new JiraSites(
                        resource.getString("id"),
                        resource.getString("name")
                );
                sites.add(site);
            }

            return sites;

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while fetching Jira sites", e);
        }
        return null;
    }

    public List<JiraProject> getJiraProjects(String zsoId, Long projectId, String cloudId) {
        try {
            JiraAuth jiraAuth = getJiraAuth(zsoId, projectId);
            if (jiraAuth == null) {
                return null;
            }
            JSONObject jiraResponse = makeJiraConnection(jiraAuth, (String token) -> {
                if (CommonUtil.isEmpty(token, cloudId)) {
                    return null;
                }
                String getProjectsUrl = JIRA_BASE_URL + "/ex/jira/" + cloudId + "/rest/api/3/project/search";
                Map<String, String> params = new HashMap<>();
                params.put("status", "live");
                params.put("maxResults", "100");

                Map<String, String> headers = new HashMap<>();
                headers.put("Authorization", "Bearer " + token);
                LOGGER.log(Level.INFO , "Token {0}", token);
                try {
                    String jiraProjectsResponse = new HttpURLConnectionInvoker(true)
                            .invokeGetHttpURLConn(
                                    getProjectsUrl,
                                    headers,
                                    params
                            );
                    return new JSONObject(jiraProjectsResponse);
                } catch (Exception e) {
                    LOGGER.log(Level.SEVERE, "Exception while fetching Jira Projects", e);
                }
                return null;
            });

            if (jiraResponse == null) {
                return null;
            }

            ArrayList<JiraProject> jiraProjects = new ArrayList<>();
            JSONArray jiraProjectsJSONArray = jiraResponse.optJSONArray("values", null);
            if (jiraProjectsJSONArray == null) {
                return null;
            }

            for (int i = 0; i < jiraProjectsJSONArray.length(); i++) {
                JiraProject project = new JiraProject(
                        jiraProjectsJSONArray.getJSONObject(i).getString("name"),
                        jiraProjectsJSONArray.getJSONObject(i).getString("key"),
                        jiraProjectsJSONArray.getJSONObject(i).getString("id")
                );
                jiraProjects.add(project);
            }

            return jiraProjects;

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while getting Jira projects list", e);
        }

        return null;
    }

    public List<JiraIssueType> getJiraIssueTypes(
            String zsoId,
            long projectId,
            String cloudId,
            String jiraProjectId
    ) {
        JiraAuth jiraAuth = getJiraAuth(zsoId, projectId);
        if (jiraAuth == null) {
            return null;
        }

        JSONObject jiraResponse = makeJiraConnection(jiraAuth, (String token) -> {
            if (CommonUtil.isEmpty(token, cloudId)) {
                return null;
            }

            String getIssueTypesUrl = JIRA_BASE_URL
                    + "/ex/jira/" + cloudId
                    + "/rest/api/3/issue/createmeta/"
                    + jiraProjectId
                    + "/issuetypes";

            Map<String, String> params = new HashMap<>();
            params.put("maxResults", "100");

            Map<String, String> headers = new HashMap<>();
            headers.put("Authorization", "Bearer " + token);

            try {
                String jiraProjectsResponse = new HttpURLConnectionInvoker(true)
                        .invokeGetHttpURLConn(
                                getIssueTypesUrl,
                                headers,
                                params
                        );
                return new JSONObject(jiraProjectsResponse);
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Exception while fetching Jira issue types", e);
            }
            return null;
        });

        if (jiraResponse == null) {
            return null;
        }

        ArrayList<JiraIssueType> issueTypes = new ArrayList<>();
        JSONArray issueTypesJSONArray = jiraResponse.optJSONArray("issueTypes");
        if (issueTypesJSONArray == null) {
            return null;
        }

        for (int i = 0; i < issueTypesJSONArray.length(); i++) {
            int hierarchyLevel = issueTypesJSONArray.getJSONObject(i).getInt("hierarchyLevel");
            if (hierarchyLevel == 0) {
                JiraIssueType issueType = new JiraIssueType(
                        issueTypesJSONArray.getJSONObject(i).getString("name"),
                        issueTypesJSONArray.getJSONObject(i).getString("id")
                );
                issueTypes.add(issueType);
            }
        }

        return issueTypes;
    }

