    private String getCloudIdFromAccessibleResources(JSONObject accessibleResources) throws JSONException {
        JSONArray resourcesArray = accessibleResources.getJSONArray("data");

        for (int i = 0; i < resourcesArray.length(); i++) {
            JSONObject resource = resourcesArray.getJSONObject(i);
            JSONArray scopes = resource.getJSONArray("scopes");
            for (int j = 0; j < scopes.length(); j++) {
                if (scopes.getString(j).equals(JIRA_SCOPE)) {
                    return resource.getString("id");
                }
            }
        }
        return null;
    }

    private JSONObject buildRequestBodyToCreateIssue(
            String jiraProject,
            String jiraIssueType,
            String issueTitle,
            String issueDescription,
            String issueLink
    ) {
        JSONObject requestBody = new JSONObject();
        JSONObject fields = new JSONObject();

        JSONObject projectField = new JSONObject();
        projectField.put("id", jiraProject);

        JSONObject issueTypeField = new JSONObject();
        issueTypeField.put("id", jiraIssueType);

        JSONObject issueDescField = new JSONObject();
        issueDescField.put("type", "doc");
        issueDescField.put("version", 1);

        JSONArray contentArr = new JSONArray();

        // Paragraph 1
        JSONObject p1 = new JSONObject();
        p1.put("type", "paragraph");

        JSONArray p1Content = new JSONArray();
        p1.put("content", p1Content);

        JSONObject linkText = new JSONObject();
        linkText.put("type", "text");
        linkText.put("text", issueLink);

        JSONArray marks = new JSONArray();
        JSONObject mark = new JSONObject();
        mark.put("type", "link");

        JSONObject attrs = new JSONObject();
        attrs.put("href", issueLink);

        mark.put("attrs", attrs);
        marks.put(mark);

        linkText.put("marks", marks);
        p1Content.put(linkText);

        // Add space text
        JSONObject spaceText = new JSONObject();
        spaceText.put("type", "text");
        spaceText.put("text", "  ");
        p1Content.put(spaceText);

        contentArr.put(p1);

        // Paragraph 2
        JSONObject p2 = new JSONObject();
        p2.put("type", "paragraph");

        JSONArray p2Content = new JSONArray();
        p2.put("content", p2Content);

        JSONObject stackText = new JSONObject();
        stackText.put("type", "text");
        stackText.put("text", issueDescription);

        p2Content.put(stackText);
        contentArr.put(p2);

        issueDescField.put("content", contentArr);

        fields.put("project", projectField);
        fields.put("issuetype", issueTypeField);
        fields.put("summary", issueTitle);
        fields.put("description", issueDescField);

        requestBody.put("fields", fields);

        return requestBody;
    }

    private JiraAuth getJiraAuth(
            String zsoId,
            long projectId
    ) {
        try {
            Criteria selectCriteria = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.JIRA, QueryConstants.EQUAL);
            selectCriteria = selectCriteria.and(
                    new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), projectId, QueryConstants.EQUAL)
            );

            Row jiraAuthRow = DBHandler.getFirstRowFromRedis(AppticsConstants.REFRESHTOKEN, selectCriteria, zsoId);
            if (jiraAuthRow != null) {
                return new JiraAuth(
                        zsoId,
                        projectId,
                        jiraAuthRow.getAs(AppticsConstants.ACCESSTOKEN, String.class),
                        jiraAuthRow.getAs(AppticsConstants.REFRESHTOKEN, String.class)
                );
            }
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while fetch cloud id for project", e);
        }
        return null;
    }

    private void addOrUpdateJiraAuth(
            long projectId,
            String zsoId,
            String accessToken,
            String refreshToken
    ) throws Exception {
        Map<String, Object> criteriaCols = new HashMap<>();
        criteriaCols.put(AppticsConstants.ZUID, projectId);
        criteriaCols.put(AppticsConstants.SERVICENAME, AppticsConstants.JIRA);
        if (MickeyUtil.isRowExist(
                AppticsConstants.REFRESHTOKEN,
                AppticsConstants.REFRESHTOKENID,
                criteriaCols,
                zsoId
        )) {
            LOGGER.log(Level.INFO, "Jira auth available for project already. Updating configs");

            Criteria updateCriteria = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.JIRA, QueryConstants.EQUAL);
            updateCriteria = updateCriteria.and(
                    new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), projectId, QueryConstants.EQUAL)
            );

            Map<String, Object> updateColWithValue = new HashMap<>();
            updateColWithValue.put(AppticsConstants.REFRESHTOKEN, refreshToken);
            updateColWithValue.put(AppticsConstants.ACCESSTOKEN, accessToken);
            updateColWithValue.put(AppticsConstants.ADDEDTIME, CalendarUtil.currentTimeMillis());

            DBHandler.updateInRedis(AppticsConstants.REFRESHTOKEN, updateCriteria, updateColWithValue, zsoId);

        } else {
            Row authRow = new Row(AppticsConstants.REFRESHTOKEN);
            authRow.set(AppticsConstants.REFRESHTOKEN, refreshToken);
            authRow.set(AppticsConstants.ACCESSTOKEN, accessToken);
            authRow.set(AppticsConstants.ZUID, projectId);
            authRow.set(AppticsConstants.SERVICENAME, AppticsConstants.JIRA);
            authRow.set(AppticsConstants.ADDEDTIME, CalendarUtil.currentTimeMillis());

            DBHandler.insertRedisCacheRow(
                    authRow,
                    AppticsConstants.REFRESHTOKEN,
                    AppticsConstants.REFRESHTOKENID,
                    zsoId
            );
        }
    }
